import heapq
from itertools import count


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self.customers: dict[str, bool] = {}
        self.tickets: dict[int, dict] = {}
        self._ticket_counter = count(1)
        self._seq_counter = count()
        # Min-heap storing tuples: (vip_rank, prio_rank, sequence, ticket_id)
        self._queue: list[tuple[int, int, int, int]] = []

    def add_customer(self, name: str, vip: bool = False) -> None:
        self.customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")
        if customer not in self.customers:
            # If customer was not registered, default to non-VIP
            self.customers[customer] = False

        ticket_id = next(self._ticket_counter)
        ticket_data = {
            "id": ticket_id,
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "queued",
        }
        self.tickets[ticket_id] = ticket_data
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        ticket = self.tickets[ticket_id]
        is_vip = self.customers.get(ticket["customer"], False)

        # VIP customers are handled before non-VIP (0 for VIP, 1 for non-VIP)
        vip_rank = 0 if is_vip else 1
        # Priorities: critical (0) > high (1) > normal (2)
        prio_map = {"critical": 0, "high": 1, "normal": 2}
        prio_rank = prio_map[ticket["priority"]]
        seq = next(self._seq_counter)

        heapq.heappush(self._queue, (vip_rank, prio_rank, seq, ticket_id))

    def next_ticket(self) -> int | None:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        while self._queue:
            *_, ticket_id = heapq.heappop(self._queue)
            ticket = self.tickets[ticket_id]
            if ticket["status"] == "queued":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self.tickets:
            raise ValueError(f"Ticket with ID {ticket_id} does not exist.")
        self.tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self.tickets:
            raise ValueError(f"Ticket with ID {ticket_id} does not exist.")
        ticket = self.tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("A closed ticket cannot be reopened.")
        if ticket["status"] != "queued":
            ticket["status"] = "queued"
            self._enqueue(ticket_id)
